    background: rgba(0, 0, 0, 0.3);
    padding: 2px 6px;
    border-radius: 4px;
    font-size: 0.85em;
    color: #ff9e64;
}

.msg-content pre {
    background: rgba(0, 0, 0, 0.4);
    border: 1px solid rgba(255, 255, 255, 0.05);
    border-radius: 8px;
    padding: 14px;
    overflow-x: auto;
    margin: 12px 0;
}

.msg-content pre code {
    background: transparent;
    padding: 0;
    color: #a9b1d6;
    font-size: 0.88rem;
}

.msg-content ul, .msg-content ol {
    margin: 8px 0 8px 20px;
}

.msg-content li {
    margin-bottom: 4px;
}

/* Typings indicator bubble */
.typing-bubble {
    display: flex;
    gap: 4px;
    padding: 12px 18px;
    border-radius: 18px;
    background: var(--bot-gradient);
    border: 1px solid rgba(255, 255, 255, 0.05);
    align-items: center;
    width: fit-content;
}

.typing-dot {
    width: 6px;
    height: 6px;
    background-color: var(--text-muted);
    border-radius: 50%;
    animation: typing 1.4s infinite ease-in-out;
}

.typing-dot:nth-child(2) {
    animation-delay: 0.2s;
}

.typing-dot:nth-child(3) {
    animation-delay: 0.4s;
}

/* INPUT CONTAINER */
.chat-input-container {
    padding: 24px 28px;
    border-top: 1px solid var(--border-color);
    background: rgba(10, 7, 18, 0.3);
}

.chat-form {
    display: flex;
    align-items: flex-end;
    gap: 14px;
    background: rgba(255, 255, 255, 0.02);
    border: 1px solid var(--border-color);
    border-radius: 16px;
    padding: 10px 14px;
    transition: all 0.3s ease;
}

.chat-form:focus-within {
    border-color: var(--border-color-focus);
    background: rgba(255, 255, 255, 0.04);
    box-shadow: 0 0 15px rgba(157, 78, 221, 0.15);
}

.chat-form textarea {
    flex: 1;
    background: transparent;
    border: none;
    outline: none;
    color: var(--text-main);
    font-family: var(--font-main);
    font-size: 0.95rem;
    resize: none;
    max-height: 120px;
    padding: 6px 0;
    line-height: 1.5;
}

.chat-form textarea::placeholder {
    color: var(--text-muted);
    opacity: 0.7;
}

.send-btn {
    background: var(--accent-gradient);
    border: none;
    color: #fff;
    width: 36px;
    height: 36px;
    border-radius: 10px;
    display: flex;
    justify-content: center;
    align-items: center;
    cursor: pointer;
    transition: all 0.25s cubic-bezier(0.4, 0, 0.2, 1);
    flex-shrink: 0;
}

.send-btn:hover {
    transform: scale(1.05) translateY(-2px);
    box-shadow: 0 4px 15px rgba(123, 44, 191, 0.4);
}

.send-btn:active {
    transform: scale(0.98);
}

.send-btn i {
    width: 16px;
    height: 16px;
}

/* ANIMATIONS */
@keyframes pulse {
    0%, 100% { opacity: 0.6; transform: scale(1); }
    50% { opacity: 1; transform: scale(1.15); }
}

@keyframes slideUp {
    from {
        opacity: 0;
        transform: translateY(12px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

@keyframes typing {
    0%, 100% { transform: translateY(0); opacity: 0.4; }
    50% { transform: translateY(-4px); opacity: 1; }
}

/* RESPONSIVE DESIGN */
@media (max-width: 600px) {
    .chat-container {
        width: 100%;
        height: 100vh;
        border-radius: 0;
        border: none;
    }
    body {
        padding: 0;
    }
    .message {
        max-width: 90%;
    }
    .chat-messages {
        padding: 16px;
    }
    .chat-input-container {
        padding: 16px;
    }
}

document.addEventListener("DOMContentLoaded", () => {
    const chatForm = document.getElementById("chat-form");
    const userInput = document.getElementById("user-input");
    const messagesContainer = document.getElementById("messages-container");
    const clearChatBtn = document.getElementById("clear-chat");

    let chatHistory = []; // Tracks [{role: "user"|"model", text: "..."}]

    // Auto-grow textarea
    userInput.addEventListener("input", function() {
        this.style.height = "auto";
        this.style.height = (this.scrollHeight - 4) + "px";
    });

    // Handle form submit
    chatForm.addEventListener("submit", (e) => {
        e.preventDefault();
        const text = userInput.value.trim();
        if (!text) return;

        sendMessage(text);
    });

    // Enter key sends message (Shift+Enter for newline)
    userInput.addEventListener("keydown", (e) => {
        if (e.key === "Enter" && !e.shiftKey) {
            e.preventDefault();
            chatForm.dispatchEvent(new Event("submit"));
        }
    });

    // Clear chat button
    clearChatBtn.addEventListener("click", () => {
        if (confirm("Are you sure you want to clear the conversation?")) {
            chatHistory = [];
            messagesContainer.innerHTML = `
                <div class="welcome-message">
                    <div class="welcome-icon">
                        <i data-lucide="bot" size="48"></i>
                    </div>
                    <h2>Welcome to Gemini Chat</h2>
                    <p>Ask anything! I can help you write code, brainstorm ideas, analyze text, or just chat.</p>
                    <div class="preset-suggestions">
                        <button class="preset-btn" onclick="sendPreset('Explain the concept of quantum computing simply.')">
                            <i data-lucide="cpu" size="16"></i> Quantum Computing
                        </button>
                        <button class="preset-btn" onclick="sendPreset('Write a python function to check if a number is prime.')">
                            <i data-lucide="code-2" size="16"></i> Python Primality Test
                        </button>
                        <button class="preset-btn" onclick="sendPreset('Brainstorm 5 creative name ideas for an eco-friendly tech startup.')">
                            <i data-lucide="lightbulb" size="16"></i> Startup Names
                        </button>
                    </div>
                </div>
            `;
            lucide.createIcons();
        }
    });

    window.sendPreset = function(text) {
        sendMessage(text);
    };

    function sendMessage(text) {
        // Remove welcome screen if present
        const welcome = document.querySelector(".welcome-message");
        if (welcome) {
            welcome.remove();
        }

        // Add user message to UI and history
        appendMessage("user", text);
        chatHistory.push({ role: "user", text: text });

        // Reset input field
        userInput.value = "";
        userInput.style.height = "auto";

        // Show typing indicator
        const typingIndicator = appendTypingIndicator();

        // Scroll to bottom
        scrollToBottom();

        // Make API request
        fetch("/api/chat", {
            method: "POST",
            headers: {
                "Content-Type": "application/json"
            },
            body: JSON.stringify({
                message: text,
                history: chatHistory
            })
        })
        .then(response => {
            if (!response.ok) {
                return response.json().then(err => { throw new Error(err.detail || "Request failed"); });
            }
            return response.json();
        })
        .then(data => {
            // Remove typing indicator
            typingIndicator.remove();

            // Append bot response to UI and history
            const botText = data.response;
            appendMessage("model", botText);
            chatHistory.push({ role: "model", text: botText });
            scrollToBottom();
        })
        .catch(error => {
            typingIndicator.remove();
            appendMessage("model", `⚠️ **Error**: ${error.message}. Please make sure you have set the \`GEMINI_API_KEY\` environment variable.`);
            scrollToBottom();
        });
    }

    function appendMessage(role, text) {
        const messageDiv = document.createElement("div");
        messageDiv.classList.add("message", role);

        const avatarDiv = document.createElement("div");
        avatarDiv.classList.add("msg-avatar");
        if (role === "user") {
            avatarDiv.innerHTML = '<i data-lucide="user"></i>';
        } else {
            avatarDiv.innerHTML = '<i data-lucide="sparkles"></i>';
        }

        const contentDiv = document.createElement("div");
        contentDiv.classList.add("msg-content");
        contentDiv.innerHTML = formatMarkdown(text);

        messageDiv.appendChild(avatarDiv);
        messageDiv.appendChild(contentDiv);

        messagesContainer.appendChild(messageDiv);
        lucide.createIcons();
    }

    function appendTypingIndicator() {
        const messageDiv = document.createElement("div");
        messageDiv.classList.add("message", "model");

        const avatarDiv = document.createElement("div");
        avatarDiv.classList.add("msg-avatar");
        avatarDiv.innerHTML = '<i data-lucide="sparkles"></i>';

        const typingDiv = document.createElement("div");
        typingDiv.classList.add("typing-bubble");
        typingDiv.innerHTML = `
            <span class="typing-dot"></span>
            <span class="typing-dot"></span>
            <span class="typing-dot"></span>
        `;

        messageDiv.appendChild(avatarDiv);
        messageDiv.appendChild(typingDiv);
        messagesContainer.appendChild(messageDiv);

        lucide.createIcons();
        return messageDiv;
    }

    function scrollToBottom() {
        messagesContainer.scrollTop = messagesContainer.scrollHeight;
    }

    // A lightweight Markdown formatter to handle basic tags:
    // Code blocks, inline code, bold, lists, paragraphs
    function formatMarkdown(text) {
        // Escape HTML to prevent injection
        let escaped = text
            .replace(/&/g, "&amp;")
            .replace(/</g, "&lt;")
            .replace(/>/g, "&gt;");

        // Code blocks: ```language ... ```
        escaped = escaped.replace(/```(?:[a-zA-Z0-9]+)?\n([\s\S]*?)```/g, (match, code) => {
            return `<pre><code>${code.trim()}</code></pre>`;
        });

        // Inline code: `code`
        escaped = escaped.replace(/`([^`]+)`/g, "<code>$1</code>");

        // Bold: **text**
        escaped = escaped.replace(/\*\*([^*]+)\*\*/g, "<strong>$1</strong>");

        // Italic: *text*
        escaped = escaped.replace(/\*([^*]+)\*/g, "<em>$1</em>");

        // Split by lines to parse lists and paragraphs
        const lines = escaped.split("\n");
        let formatted = "";
        let inList = false;

        for (let line of lines) {
            let lineTrim = line.trim();

            // Nested list item or bullet item
            if (lineTrim.startsWith("- ") || lineTrim.startsWith("* ")) {
                if (!inList) {
                    formatted += "<ul>";
                    inList = true;
                }
                formatted += `<li>${lineTrim.substring(2)}</li>`;
            } else {
                if (inList) {
                    formatted += "</ul>";
                    inList = false;
                }
                if (lineTrim) {
                    // Check if it's already a structural tag (like pre)
                    if (lineTrim.startsWith("<pre>") || lineTrim.endsWith("</pre>")) {
                        formatted += line;
                    } else {
                        formatted += `<p>${line}</p>`;
                    }
                }
            }
        }

        if (inList) {
            formatted += "</ul>";
        }

        return formatted;
    }
});

